function fnv(s){let h=0xcbf29ce484222325n;const p=0x100000001b3n;for(const ch of s){h^=BigInt(ch.codePointAt(0));h=(h*p)&0xffffffffffffffffn;}return h.toString(16);}
const out=[];
for (const it of $input.all()) {
  const j=it.json; const txt=String(j.conteudo||'').trim(); if(!txt) continue;
  const size=1200, ov=150; const parts=[];
  if (txt.length<=size) parts.push(txt); else { for(let i=0;i<txt.length && parts.length<50;i+=size-ov) parts.push(txt.slice(i,i+size)); }
  parts.forEach((p,idx)=>out.push({json:{
    conteudo:p, resumo:String(j.resumo||''), tipo:j.tipo||'nota', origem:j.origem||'desconhecida',
    projeto:String(j.projeto||''), link:String(j.link||''), data_ref:j.data_ref||new Date().toISOString(),
    metadados:JSON.stringify({...(j.metadados||{}), parte:idx+1, de:parts.length}),
    hash_trecho:fnv((j.tipo||'')+'|'+(j.link||'')+'|'+(j.data_ref||'')+'|'+p)}}));
}
return out;
